mapper.update:
UPDATE t_pay_record
SET trade_no = IFNULL(#{tradeNo}, trade_no),
    pay_amount = IFNULL(#{payAmount}, pay_amount),
    pay_status = #{successStatus}
WHERE out_trade_no = #{outTradeNo}
  AND pay_status = #{expectedStatus}
  AND del_flag = 0
LIMIT 1

mapper.select:
SELECT *
FROM t_pay_record
WHERE pay_status = #{payStatus}
  AND business_status = #{failedStatus}
  AND COALESCE(business_retry_count, 0) < #{maxRetryCount}
  AND del_flag = 0
ORDER BY update_time ASC, id ASC
LIMIT #{limit}
